int main() {
    string line;
    getline(cin, line);
    vector<string> task = split(line, " ");
    int n = task.size() / 2;
    vector<pair<int, int>> taskList(n);
    for (int i = 0; i <  n ; i++) {
        taskList[i] = {stoi(task[2 * i]), stoi(task[2 * i + 1])};
    }
​
    getline(cin , line);
    vector<string> tmp = split(line, " ");
​
    int capacity = stoi(tmp[0]);
    int executorCount = stoi(tmp[1]);

    // 用于队列中的任务
    queue<pair<int, int>> taskQueue;
    // 根据结束时间进行排序
    priority_queue<pair<int, int>, vector<pair<int, int>>, Compare> busyExecutor;
    // 存储当前空闲执行者id
    priority_queue<int, vector<int>, greater<int>>  freeExecutor;

    for (int i = 1 ; i <= executorCount; i++) {
        freeExecutor.push(i);
    }
​
    int currrentTime = 1;
    int dropOutCount = 0;
    int pos = 0;
    int lastFinishTime = -1;
    while (pos < n || !taskQueue.empty()) {
        // 将结束工作的生产者放到空闲队列中
        while (!busyExecutor.empty() && busyExecutor.top().second <= currrentTime) {
            pair<int, int> tmp = busyExecutor.top();
            busyExecutor.pop();
            // 放入空闲队列中
            freeExecutor.push(tmp.first);
        }
​
        // 空闲生产者去任务队列中找任务
        if (!freeExecutor.empty()) {
            while (!freeExecutor.empty() && !taskQueue.empty()) {
                int executorId = freeExecutor.top();
                freeExecutor.pop();
​
                pair<int, int> task = taskQueue.front();
                taskQueue.pop();
                busyExecutor.push({executorId, currrentTime + task.second});
                lastFinishTime = max(lastFinishTime, currrentTime + task.second);
            } 
        }
​
        // 尝试将当前时机投递的任务放入队列中
        if (pos < n && currrentTime >= taskList[pos].first) {
            pair<int, int> task = taskList[pos];
            pos++;
            taskQueue.push(task);
​
​
            // 丢弃情况情况处理
            while (taskQueue.size() > capacity) {
                taskQueue.pop();
                dropOutCount++;
            }
        }
​
        // 空闲生产者去任务队列中找任务执行
        if (!freeExecutor.empty()) {
            while (!freeExecutor.empty() && !taskQueue.empty()) {
                int executorId = freeExecutor.top();
                freeExecutor.pop();
                pair<int, int> task = taskQueue.front();
                taskQueue.pop();
                busyExecutor.push({executorId, currrentTime + task.second});
                lastFinishTime = max(lastFinishTime, currrentTime + task.second);
            } 
        }
        currrentTime++;
    }
    cout << lastFinishTime << " " << dropOutCount;
    return 0;
}
