package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
    "container/heap"
)
​
// 任务队列
type TaskQueue struct {
    tasks []Task
}
​
func (q *TaskQueue) Push(task Task) {
    q.tasks = append(q.tasks, task)
}
​
func (q *TaskQueue) Pop() Task {
    task := q.tasks[0]
    q.tasks = q.tasks[1:]
    return task
}
​
func (q *TaskQueue) Size() int {
    return len(q.tasks)
}
​
// 任务结构体
type Task struct {
    startTime int
    duration  int
}
​
// 执行者优先队列（最小堆）
type ExecutorHeap []Executor
​
func (h ExecutorHeap) Len() int           { return len(h) }
func (h ExecutorHeap) Less(i, j int) bool { return h[i].freeTime < h[j].freeTime || (h[i].freeTime == h[j].freeTime && h[i].id < h[j].id) }
func (h ExecutorHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
​
func (h *ExecutorHeap) Push(x interface{}) {
    *h = append(*h, x.(Executor))
}
​
func (h *ExecutorHeap) Pop() interface{} {
    old := *h
    n := len(old)
    x := old[n-1]
    *h = old[0 : n-1]
    return x
}
​
// 执行者结构体
type Executor struct {
    id       int
    freeTime int
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取任务
    scanner.Scan()
    taskStr := scanner.Text()
    taskData := strings.Split(taskStr, " ")
​
    n := len(taskData) / 2
    taskList := make([]Task, n)
​
    for i := 0; i < n; i++ {
        startTime, _ := strconv.Atoi(taskData[2*i])
        duration, _ := strconv.Atoi(taskData[2*i+1])
        taskList[i] = Task{startTime, duration}
    }
​
    // 读取执行者和容量
    scanner.Scan()
    params := strings.Split(scanner.Text(), " ")
    capacity, _ := strconv.Atoi(params[0])
    executorCount, _ := strconv.Atoi(params[1])
​
    // 任务队列
    var taskQueue TaskQueue
​
    // 忙碌执行者最小堆
    busyExecutor := &ExecutorHeap{}
    heap.Init(busyExecutor)
​
    // 空闲执行者最小堆
    freeExecutor := &ExecutorHeap{}
    heap.Init(freeExecutor)
​
    for i := 1; i <= executorCount; i++ {
        heap.Push(freeExecutor, Executor{id: i, freeTime: 0})
    }
​
    currentTime := 1
    dropOutCount := 0
    pos := 0
    lastFinishTime := -1
​
    for pos < n || taskQueue.Size() > 0 {
        // 将空闲执行者放回空闲队列
        for busyExecutor.Len() > 0 && (*busyExecutor)[0].freeTime <= currentTime {
            executor := heap.Pop(busyExecutor).(Executor)
            heap.Push(freeExecutor, executor)
        }
​
        // 空闲执行者执行任务
        for freeExecutor.Len() > 0 && taskQueue.Size() > 0 {
            executor := heap.Pop(freeExecutor).(Executor)
            task := taskQueue.Pop()
            executor.freeTime = currentTime + task.duration
            heap.Push(busyExecutor, executor)
            if executor.freeTime > lastFinishTime {
                lastFinishTime = executor.freeTime
            }
        }
​
        // 添加新任务到队列
        if pos < n && currentTime >= taskList[pos].startTime {
            taskQueue.Push(taskList[pos])
            pos++
​
            // 丢弃超出容量的任务
            for taskQueue.Size() > capacity {
                taskQueue.Pop()
                dropOutCount++
            }
        }
​
        // 再次尝试分配任务
        for freeExecutor.Len() > 0 && taskQueue.Size() > 0 {
            executor := heap.Pop(freeExecutor).(Executor)
            task := taskQueue.Pop()
            executor.freeTime = currentTime + task.duration
            heap.Push(busyExecutor, executor)
            if executor.freeTime > lastFinishTime {
                lastFinishTime = executor.freeTime
            }
        }
​
        currentTime++
    }
​
    fmt.Println(lastFinishTime, dropOutCount)
}
